import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/ViewSales.css";

const ViewSales = () => {
  const userId = sessionStorage.getItem("userId");
  const [sales, setSales] = useState([]);
  const [loading, setLoading] = useState(true);
  const [payoutTotal, setPayoutTotal] = useState(0);
  const [paidAmount, setPaidAmount] = useState(null);

  useEffect(() => {
    const fetchSales = async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/sales/${userId}`);
        const data = await res.json();
        setSales(data);
        const total = data.reduce((sum, sale) => sum + parseFloat(sale.price || 0), 0);
        setPayoutTotal(total);
      } catch (err) {
        console.error("Failed to load sales:", err);
      } finally {
        setLoading(false);
      }
    };
    fetchSales();
  }, [userId]);

  const handlePayout = () => {
    const payout = (payoutTotal * 0.95).toFixed(2);
    setPaidAmount(payout);
    setPayoutTotal(0);
  };

  const updateSaleField = async (saleId, field) => {
    try {
      await fetch(`${API_BASE_URL}/api/sales/${saleId}/${field}`, { method: "PUT" });
      setSales((prev) =>
        prev.map((s) => (s.id === saleId ? { ...s, [field === "mark-paid" ? "payout_status" : "reviewed"]: true } : s))
      );
    } catch (err) {
      console.error(`Failed to mark ${field}:`, err);
    }
  };

  const deleteSale = async (saleId) => {
    if (!window.confirm("Are you sure you want to delete this sale?")) return;
    try {
      await fetch(`${API_BASE_URL}/api/sales/${saleId}`, { method: "DELETE" });
      setSales((prev) => prev.filter((s) => s.id !== saleId));
    } catch (err) {
      console.error("Failed to delete sale:", err);
    }
  };

  return (
    <div className="page-container">
      <Navbar />
      <main className="viewsales-main">
        <h2 className="viewsales-heading">💼 Sales Dashboard</h2>

        {loading ? (
          <p className="viewsales-loading">Loading sales...</p>
        ) : sales.length === 0 ? (
          <p className="viewsales-empty">You haven't made any sales yet.</p>
        ) : (
          <div className="viewsales-grid">
            {sales.map((sale) => (
              <div key={sale.id} className="viewsales-card">
                <h3>{sale.title}</h3>
                <p><strong>Listing ID:</strong> #{sale.listing_id}</p>
                <p><strong>Sold For:</strong> ${parseFloat(sale.price).toFixed(2)}</p>
                <p><strong>Buyer:</strong> {sale.buyer_name} ({sale.buyer_email})</p>
                <p><strong>Delivery ETA:</strong> {new Date(sale.estimated_delivery).toLocaleDateString()}</p>
                <p><strong>Payout Status:</strong> {sale.payout_status === 'paid' ? "✅ Paid" : "⏳ Pending"}</p>
                <p><strong>Reviewed:</strong> {sale.reviewed ? "✅ Yes" : "❌ No"}</p>

                <div className="viewsales-buttons">
                  {!sale.reviewed && (
                    <button onClick={() => updateSaleField(sale.id, "reviewed")} className="btn reviewed">
                      ✅ Mark as Reviewed
                    </button>
                  )}
                  {sale.payout_status === 'pending' && (
                    <button onClick={() => updateSaleField(sale.id, "mark-paid")} className="btn paid">
                      💰 Mark as Paid
                    </button>
                  )}
                  <button onClick={() => deleteSale(sale.id)} className="btn delete">
                    🗑️ Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}

        <div className="viewsales-summary">
          <h3>Total Pending Payout: <span>${payoutTotal.toFixed(2)}</span></h3>
          {payoutTotal > 0 && (
            <button onClick={handlePayout} className="btn payout">
              💸 Payout Now (5% Fee)
            </button>
          )}
          {paidAmount && (
            <div className="paid-message">
              ✅ You got paid: <strong>${paidAmount}</strong> (after 5% fee)
            </div>
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default ViewSales;
